namespace bettercpp{class MiseryEngine{private:int l;void log(std::string s,std::string m){std::cout<<"[MISERY-SEC]["<<s<<"] "<<m<<std::endl;}public:MiseryEngine(int b){l=b;}void run(){std::cout<<"=== MISERY: Memory Engine ==="<<std::endl;log("INIT","Creating isolated runtime...");log("LIMIT","Sandbox restriction: "+std::to_string(l)+" MB");std::this_thread::sleep_for(std::chrono::milliseconds(400));log("GUARD","Monitoring allocation...");for(int i=1;i<=3;++i){log("CHECK","Segment "+std::to_string(i)+" -> alloc: "+std::to_string((l/3)*i)+" MB");std::this_thread::sleep_for(std::chrono::milliseconds(200));}std::cout<<"-----------------------------"<<std::endl;log("YIELD","Finished cleanly. No leaks.");}};}int main(int c,char* v[]){int a=(c>1)?std::stoi(v[1]):64;bettercpp::MiseryEngine e(a);e.run();return 0;}
